"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[97185],{97185:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/a-murder-is-announced.png\\"\\n          title=\\"살인을 예고합니다\\"\\n          author=\\"애거서 크리스티\\"\\n          publisher=\\"황금가지\\"\\n          publishedDate=\\"2013-05-27\\"\\n          isbn=\\"9788982737077\\"\\n          rating=4\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n신문 광고로 살인을 <mark>예고</mark>한다는 설정이 독창적이다.  \\n> “살인이 예고됩니다. 날짜는 10월 29일 금요일, 오후 6시 30분. 장소는 리틀 패덕스. 관심 있는 분은 오시기 바랍니다.”\\n\\n주민들은 이 광고를 연극이거나 장난이라고 생각하고, 일부는 호기심에 정말 리틀 패덕스 저택에 찾아온다.  \\n저택의 주인은 당황하지만 손님들을 맞이하고, 정해진 시간이 되자 갑자기 정전이 발생한다.  \\n<br>\\n그 순간, 총성이 울리고, 괴한이 침입하지만 그 자리에서 사살된다.  \\n<br>\\n연극은 이렇게 괴한의 살인미수로 마무리되는 듯했지만, ```미스 마플```에 의해 새로운 진실이 밝혀진다.  \\n<br>\\n가계도가 복잡해서 조금 힘들었지만, 설정이 독특해서 흥미롭게 읽은 작품."}')}}]);